from 写入第二遍 import add
add('01_001',2,'16:9，云天远景空镜，云层占满横幅，较暗云块位于中央；固定机位。','远处两次轰响隔着一小拍传来，云层下侧极薄的灰尘被震得轻颤，随后重新摊平；高处云层仍缓慢移动，画内没有攻击实体。','铅蓝天空，深浅不一的灰蓝云层重叠，低处一层米灰薄尘。','云天自然冷白漫射，云层本身无新增发光。','两声远处闷轰，一轻一重，低频余响向城内退散。',kind='state',phase='state',node={'场景焦点':'战斗声传播至城内其他地点'},meaning='原作天空与两次轰响保留，画面转入城内避难线。',characters=[])
add('01_002',2.5,'16:9，石屋外侧中远景，高墙与拱窗位于画面右侧，屋面在左下近层，远处烟柱在左后；镜头沿竖长拱窗上摇，从石窗台到上拱落幅，远处烟柱始终留在左侧空隙。','远处烟柱向上拖长，外侧墙面随着一阵低震落下一点细灰；拱窗横档的阴影轻颤后停住，窗内没有人影出现。','灰米石墙、深灰窗框与拱形石窗台，左下蓝灰屋顶；远处深灰残屋轮廓和米灰烟柱，后面铅蓝云天。','开阔云天冷白柔光照亮石墙外侧，窗洞内侧较暗。','远处轰响余波接石墙细灰滑落，窗框很轻地咯一下。',phase='state',kind='state',node={'场景':'避难房间外部'},meaning='竖长建筑原格按上摇展开，连接到房内治疗与对话。',characters=[])
add('01_003',4,'16:9，室内双人中近景，青梅男居左，青梅女居右，头肩与上臂在画内；先以两人同框起幅，男说完时相机短移向右，落幅仍留男盔面侧缘与女正脸。','青梅男听着窗外轰响，把盔面转向青梅女，肩背绷着，开口评估；青梅女先望向窗的画外方向，眼睛圆睁、嘴微张，听完才把视线收回他盔面。她短短应了一声，手上的动作仍留在床边画外，眉间逐渐多出一条担忧折线，男的盔面没有再转开。','后方米褐木墙与一条深褐竖梁，窗外冷灰亮色只在侧边窄隙显露。','画外拱窗透入冷白柔光，室内木面返少量暖灰光。','窗框余震逐渐停住，外头闷轰仍低低延续；室内衣料细响。',ja=['…彼女、苦戦してるな。','そうね…'],tone='青梅男低声判断；青梅女担忧地短答，视线在回应后回到床侧任务。',kind='mixed',phase='state',node={'场景':'女主席治疗房间','青梅男.阶段':'留在床边关注战况','青梅女.阶段':'治疗任务中回应'},card={'opening':'两人仍守着床边，远处战斗声牵住注意。','beats':['男转盔面评估','女从窗边收回视线短答，眉间显出担忧'],'coupling':'外头战况进入房内谈话，而床边任务没有重置。','landing':'女注意仍有一部分放在床边，男尚未离房。'})
